	var unsupported abiError
	if generating && errors.As(err, &unsupported) {
		return fmt.Errorf("%s at %s: %w; tree-sitter-cli %s may no longer generate ABI 14, so pass -tree-sitter-cli <older version>", url, ref, err, version)
	}
